oxy_webhelp_navlinks = {"k8s_workload_protection-d39536e26458":{"topics":[{"title":"Deployment architecture for Kubernetes protection","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> serves as the control plane for Kubernetes protection. A         connected Rubrik cluster stores the Persistent Volume backups.<\/p>","href":"kubernetes\/k8s_deployment_architecture.html","attributes":{"data-id":"k8s_deployment_architecture"},"menu":{"hasChildren":false},"tocID":"k8s_deployment_architecture-d39536e26471","topics":[]},{"title":"Kubernetes protection images","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> deploys container images on your Kubernetes cluster as part of         Kubernetes protection.<\/p>","href":"kubernetes\/k8s_protection_images.html","attributes":{"data-id":"k8s_protection_images"},"menu":{"hasChildren":false},"tocID":"k8s_protection_images-d39536e26484","next":"k8s_protection_images-d39536e26484"},{"title":"Resource requirements for Kubernetes protection components","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> deploys three components in the             <code class=\"ph codeph\">rubrik-kupr<\/code> namespace on your Kubernetes cluster. Each component         has default CPU, memory, and ephemeral storage requests and limits.<\/p>","href":"kubernetes\/k8s_resource_requirements.html","attributes":{"data-id":"k8s_resource_requirements"},"menu":{"hasChildren":false},"tocID":"k8s_resource_requirements-d39536e26508","topics":[]},{"title":"Kubernetes protection prerequisites","shortdesc":"<p class=\"shortdesc\">There are common and specific prerequisites for Kubernetes protection.<\/p>","href":"kubernetes\/k8s_prereqs.html","attributes":{"data-id":"k8s_prereqs"},"menu":{"hasChildren":false},"tocID":"k8s_prereqs-d39536e26524","next":"k8s_prereqs-d39536e26524"},{"title":"Kubernetes protection requirements","shortdesc":"<p class=\"shortdesc\">You can use <span class=\"ph\">Rubrik Security Cloud<\/span> to secure your on-premise or public cloud         Kubernetes clusters by protecting either entire Kubernetes namespaces or specific subsets         within a namespace using the protection set filtering feature.<\/p>","href":"kubernetes\/k8s_protection.html","attributes":{"data-id":"k8s_protection"},"menu":{"hasChildren":false},"tocID":"k8s_protection-d39536e26620","next":"k8s_protection-d39536e26620"},{"title":"Kubernetes multi-networking for backup traffic","shortdesc":"<p class=\"shortdesc\">You can configure a dedicated network for Rubrik backup and restore traffic on         on-premises Kubernetes clusters to improve performance and isolate backup traffic from         application traffic. This feature requires Rubrik CDM versions 9.4.2 and later.<\/p>","href":"kubernetes\/k8s_multi_networking.html","attributes":{"data-id":"k8s_multi_networking"},"menu":{"hasChildren":false},"tocID":"k8s_multi_networking-d39536e26757","topics":[]},{"title":"Node Proxy transport for Kubernetes backups","shortdesc":"<p class=\"shortdesc\">The Node Proxy transport routes backup and restore traffic for Rubrik Backup Agent         pods, including backups of OpenShift virtual machines, over a dedicated backup network         without assigning a routable IP address to each pod.<\/p>","href":"kubernetes\/k8s_node_proxy_transport.html","attributes":{"data-id":"k8s_node_proxy_transport"},"menu":{"hasChildren":false},"tocID":"k8s_node_proxy_transport-d39536e26768","topics":[]},{"title":"Kubernetes cluster onboarding","shortdesc":"<p class=\"shortdesc\">To onboard your Kubernetes cluster, add it to your <span class=\"ph\">RSC<\/span> domain and         provide <span class=\"ph\">RSC<\/span> with access to the cluster and sufficient         permissions.<\/p>","href":"kubernetes\/k8s_cluster_onboard_discover_rsc.html","attributes":{"data-id":"k8s_cluster_onboard_discover_rsc"},"menu":{"hasChildren":false},"tocID":"k8s_cluster_onboard_discover_rsc-d39536e26779","next":"k8s_cluster_onboard_discover_rsc-d39536e26779"},{"title":"Least privilege configuration for Kubernetes","shortdesc":"<p class=\"shortdesc\">You can set up your Kubernetes kubeconfig with the least privileges so that only         minimal RBAC permissions are assigned to users and service accounts.<\/p>","href":"kubernetes\/least_privilege_configuration_K8S.html","attributes":{"data-id":"least_privilege_configuration_K8S"},"menu":{"hasChildren":false},"tocID":"least_privilege_configuration_K8S-d39536e27041","next":"least_privilege_configuration_K8S-d39536e27041"},{"title":"Kubernetes labels","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> integrates with Kubernetes native labels to manage data         protection, enabling you to use Kubernetes labels to identify and group resources, and then         associate those labels with SLA Domains.<\/p>","href":"kubernetes\/kubernetes_labels.html","attributes":{"data-id":"kubernetes_labels"},"menu":{"hasChildren":false},"tocID":"kubernetes_labels-d39536e27096","next":"kubernetes_labels-d39536e27096"},{"title":"Protection sets for Kubernetes cluster workloads","shortdesc":"<p class=\"shortdesc\">A Kubernetes cluster protection set define the resources to protect on a Kubernetes         cluster. A cluster protection set can include an entire Kubernetes namespace or a subset of         resources within a namespace.<\/p>","href":"kubernetes\/k8s_cluster_protection_set.html","attributes":{"data-id":"k8s_cluster_protection_set"},"menu":{"hasChildren":false},"tocID":"k8s_cluster_protection_set-d39536e27173","next":"k8s_cluster_protection_set-d39536e27173"},{"title":"Kubernetes resource exclusion with Velero labels","shortdesc":"<p class=\"shortdesc\">Exclude specific Kubernetes resources from <span class=\"ph\">RSC<\/span> backup by applying a         Velero label to those resources when protection set exclusion filters are not a viable         option.<\/p>","href":"kubernetes\/k8s_velero_exclude_label.html","attributes":{"data-id":"k8s_velero_exclude_label"},"menu":{"hasChildren":false},"tocID":"k8s_velero_exclude_label-d39536e27266","topics":[]},{"title":"Application protection sets","shortdesc":"<p class=\"shortdesc\">An application protection set protects enterprise workloads spanning multiple         Kubernetes namespaces as a single unit.<\/p>","href":"kubernetes\/k8s_application_protection_set.html","attributes":{"data-id":"k8s_application_protection_set"},"menu":{"hasChildren":false},"tocID":"k8s_application_protection_set-d39536e27280","next":"k8s_application_protection_set-d39536e27280"},{"title":"Browse Kubernetes snapshots","shortdesc":"<p class=\"shortdesc\">You can use <span class=\"ph\">RSC<\/span> to browse the resources in a Kubernetes snapshot for         protection sets and virtual machines.<\/p>","href":"kubernetes\/k8s_browse_kubernetes_snapshots.html","attributes":{"data-id":"k8s_browse_kubernetes_snapshots"},"menu":{"hasChildren":false},"tocID":"k8s_browse_kubernetes_snapshots-d39536e27327","next":"k8s_browse_kubernetes_snapshots-d39536e27327"},{"title":"OpenShift Virtual Machine workload","shortdesc":"<p class=\"shortdesc\">You can use <span class=\"ph\">RSC<\/span> to protect containers and virtual machines managed on         Kubernetes OpenShift clusters.<\/p>","href":"kubernetes\/k8s_openshift_clusters.html","attributes":{"data-id":"k8s_openshift_clusters"},"menu":{"hasChildren":false},"tocID":"k8s_openshift_clusters-d39536e27352","next":"k8s_openshift_clusters-d39536e27352"},{"title":"Kubernetes workload protection policies","shortdesc":"<p class=\"shortdesc\">In <span class=\"ph\">RSC<\/span>, you can take both policy-based and on-demand snapshots of         Kubernetes protection sets.<\/p>","href":"kubernetes\/k8s_workload_protection_policies.html","attributes":{"data-id":"k8s_workload_protection_policies"},"menu":{"hasChildren":false},"tocID":"k8s_workload_protection_policies-d39536e27509","next":"k8s_workload_protection_policies-d39536e27509"},{"title":"Kubernetes snapshot retention","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> allows changing the retention period of Kubernetes snapshots with         the help of SLA Domains. Kubernetes snapshot retention works only with Rubrik clusters         running Rubrik CDM version 7.0.2-p2 and later.<\/p>","href":"kubernetes\/k8s_snapshot_retention.html","attributes":{"data-id":"k8s_snapshot_retention"},"menu":{"hasChildren":false},"tocID":"k8s_snapshot_retention-d39536e27569","next":"k8s_snapshot_retention-d39536e27569"},{"title":"StorageClass mapping for Kubernetes","shortdesc":"<p class=\"shortdesc\"><code class=\"ph codeph\">StorageClass<\/code> mapping provides the ability to select or define new         storage tiers when restoring Kubernetes workloads to a different cluster or         environment.<\/p>","href":"kubernetes\/k8s_storage_class_mapping.html","attributes":{"data-id":"k8s_storage_class_mapping"},"menu":{"hasChildren":false},"tocID":"k8s_storage_class_mapping-d39536e27604","next":"k8s_storage_class_mapping-d39536e27604"},{"title":"Resource transforms for Kubernetes recovery","shortdesc":"<p class=\"shortdesc\">You can apply a resource transformation to modify a Kubernetes resource manifest         during recovery without changing the original snapshot or source cluster.<\/p>","href":"kubernetes\/k8s_resource_transforms.html","attributes":{"data-id":"k8s_resource_transforms"},"menu":{"hasChildren":false},"tocID":"k8s_resource_transforms-d39536e27651","next":"k8s_resource_transforms-d39536e27651"},{"title":"<span class=\"ph\">RSC<\/span> Custom resource definitions","shortdesc":"<p class=\"shortdesc\">You can use the <span class=\"ph\">RSC<\/span> custom resource definitions to create custom         resources for backup and recovery workflows using APIs native to Kubernetes.<\/p>","href":"kubernetes\/K8s_crd_rsc.html","attributes":{"data-id":"K8s_crd_rsc"},"menu":{"hasChildren":false},"tocID":"K8s_crd_rsc-d39536e27684","next":"K8s_crd_rsc-d39536e27684"},{"title":"<span class=\"ph\">Anomaly Detection<\/span> for Kubernetes","shortdesc":"<p class=\"shortdesc\">You can enable <span class=\"ph\">Anomaly Detection<\/span> for Kubernetes virtual machines and protection         sets to identify and analyze anomalous events that can indicate a ransomware         attack.<\/p>","href":"kubernetes\/anomaly_detection_k8.html","attributes":{"data-id":"anomaly_detection_k8"},"menu":{"hasChildren":false},"tocID":"anomaly_detection_k8-d39536e28130","topics":[]}]}};